insert into public.ar_reels_discovery_questions(id,reel_id,prompt,options) values('lesson-a6afdd1435d5263d-q1','lesson-a6afdd1435d5263d','In the lesson, torque is written τ = r × F. What does r mean?','["Radius of the Earth","Resistance","Distance of the force from the pivot","Rate of rotation"]'::jsonb) on conflict(id) do nothing;
