insert into public.ar_reels_discovery_questions(id,reel_id,prompt,options) values('lesson-a6afdd1435d5263d-q2','lesson-a6afdd1435d5263d','A force F at distance r is balanced by a force 2F at what distance?','["2r","4r","r","r/2"]'::jsonb) on conflict(id) do nothing;
insert into ar_reels_private.discovery_answer_keys(question_id,correct_index,explanation) values('lesson-a6afdd1435d5263d-q2',3,'F × r = 2F × (r/2), so the torques are equal.') on conflict(question_id) do nothing;
